$_MODULE['<{amazonmarketplacepro}prestashop>configure_5ee6f3e1aae989cfd5b4bd83d235e0f8'] = 'Les effacer maintenant';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_6ada5ba7b164dbad1d1620f4f12963b6'] = 'Suppression des données acheteur';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4ab9e6c00c5055c58feffff5ae55cd84'] = 'Activée (exigée par la conformité Amazon)';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_d15305d7a4e34e02489c74a5ef542f36'] = 'Désactivée';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9a89fce15c653813bba97088f4242469'] = 'Désactiver cette option revient à conserver les données acheteur d\'Amazon plus longtemps qu\'Amazon ne l\'autorise. Ne le faites que si une obligation légale l\'exige et que vous pouvez la démontrer.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_114fc58e687755f400c4ff77e00b9cf7'] = 'Anonymiser également le client et l\'adresse PrestaShop';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_06d16f3c4536d713eafb1f97f25657f4'] = 'Non (recommandé)';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_b3a631ecd8088b96eeab29ebb7670789'] = 'Désactivée par défaut, volontairement. PrestaShop compose ses factures à partir de l\'adresse enregistrée : l\'anonymiser modifie donc des documents que la loi peut vous imposer de conserver intacts — et une facture que vous devez conserver constitue précisément l\'exception prévue par la politique d\'Amazon. Ne l\'activez qu\'après avoir pris conseil. Lorsqu\'elle est active, un client n\'est anonymisé que si toutes ses commandes sont des commandes Amazon déjà effacées ; la ville, le code postal et le pays sont conservés afin que le traitement de la TVA reste justifiable.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4afb955a8ca5e46fdaf13febfabde9b0'] = 'Groupe de clients pour les acheteurs Amazon';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_650e8746625f41e4234739e9894cbb78'] = '-- Valeur par défaut de la boutique --';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_67b7390afec4abee3eaecd923f291c15'] = 'Panier distant (réserver le stock des commandes non payées)';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_f9f2d03af364aa656f60472f050f5ce9'] = 'Amazon présente un paiement en cours comme une commande « Pending ». Avec cette option, le module retire immédiatement ces unités du stock PrestaShop afin qu\'aucun autre canal ne puisse les vendre, et les restitue si la commande ne devient jamais payable. Nécessite l\'import des commandes Pending — le module s\'en charge automatiquement une fois l\'option activée — ainsi que la tâche cron remote_cart pour solder les réservations.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_606e569ed905da68a3f26de02575c6d9'] = 'Libérer une réservation après';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4e9a4f12657cf4a16631d3bfbbd3ea93'] = 'Délai de grâce avant que le stock d\'une commande toujours bloquée en Pending ne soit restitué. 4 heures est une valeur sûre — Amazon peut mettre un certain temps à faire passer une commande en Unshipped.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_a2d4829bd7afcb0622263a02a3b7a5fc'] = 'Commandes sans stock suffisant';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_64f05d6bfbce6140c765c29e952478b7'] = 'Créer quand même la commande PS';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9d7f6ecb0a0a1a38c076bc7a432c4907'] = 'Mettre en attente dans Commandes en attente pour examen manuel';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_dacbbee8d1ca69a51619dc28dcd68e21'] = 'Lorsque l\'option est active, les commandes préparées dont les produits manquent de stock (et qui ne peuvent pas être commandées en rupture) attendent dans l\'onglet Commandes en attente au lieu de devenir des commandes PS.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_7a8156b022b1920dc000a4274b89a638'] = 'Transporteur par défaut';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9e98c820ff3d4cea82c3d4a4412c9471'] = '-- Aucun --';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_ac8d0bb27bf0dea8f2b54d14c28511e6'] = 'Statut de commande par défaut';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_12dbd64f2bc9a6277ee7b95e9a2349dd'] = 'Acheminement des commandes importées';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_5cbc8ff529ecab618089ef063e3be9d2'] = 'Amazon vous indique le délai de livraison promis à l\'acheteur. Faites correspondre chacun d\'eux à un transporteur PrestaShop afin que les commandes importées portent le bon mode de livraison ; les délais sans correspondance utilisent le transporteur par défaut ci-dessus.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9fd1338f1dd68b2455075cc183be657f'] = 'Délai de livraison Amazon';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_15f87e0fa572c90443e2c0dc75d66819'] = '-- Transporteur par défaut --';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4fb6f1cf6de6ffac53ce3a98e1263f7a'] = 'Règles de statut avancées';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_1eb7e0300a389884bba094f84a1dfce1'] = 'Donnez à certains types de commandes leur propre statut PrestaShop — par exemple les commandes Prime dans un statut voyant que votre entrepôt ne peut pas manquer, ou les commandes FBA directement en Expédiée. Les règles sont évaluées de haut en bas et la première correspondance l\'emporte ; « Indifférent » ignore ce critère. Une règle sans statut est ignorée.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_be7938e9a87618a98a7b6b47e12aa44b'] = 'Prime';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_84806d51f6ac4f75d8000b3cc6e56bb3'] = 'FBA';
